questionvariables.text:
/* pdec: exact decimal display of a value with at most 4 decimal places */
pdec(v) := if integerp(v) then v elseif integerp(10*v) then dispdp(float(v),1) elseif integerp(100*v) then dispdp(float(v),2) elseif integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
/* Design: dice with 6 and 4 faces; sums and products, randomised dice and spinners. op 0 sum, 1 product. Source: adapted from SMP GCSE Foundation book 2, chapter 5, section A, A1 and A2. */
C: [[6,0,3,5],[8,1,8,30],[4,0,4,5],[5,1,15,10],[4,1,2,3],[8,0,10,7],[6,1,6,15],[5,0,5,4],[8,1,20,18],[4,0,3,6]];
ix: 1+rand(10);
s: C[ix][1]; op: C[ix][2]; k: C[ix][3]; m: C[ix][4];
sc(a,b) := if op=0 then a+b else a*b;
S: flatten(makelist(makelist(sc(a,b), b,1,s), a,1,6));
G: makelist(makelist(if b<=s then sc(a,b) else 0, b,1,8), a,1,6);
n: 6*s;
ck: length(sublist(S, lambda([v], v=k)));
cg: length(sublist(S, lambda([v], v>m)));
cm: length(sublist(S, lambda([v], v=m)));
nd: length(unique(S));
ta1: n; ta2: ck/n; ta3: cg/n;
tl2: min(1/200,ta2/20); tl3: min(1/200,ta3/20);
/* diagnostics */
add1: 6+s;
eq2: 1/nd;
wrongn2: ck/(6+s);
ge3: (cg+cm)/n;
wrongn3: cg/(6+s);
